from research_helpers import *
a=ev('https://www.juki.co.jp/smt/en/products/','Current electronic assembly catalogue reviewed. Pick-and-place and insertion platforms qualify as industrial robotic assembly; ordinary sewing machines and unrelated electronics equipment not automatically included.')
