products=[]
for name,desc in [('LX-8','Flexible robotic component pick-and-place assembly platform.'),('RS-2','Modular robotic component pick-and-place assembly platform.'),('RX-8','High-speed modular robotic component pick-and-place assembly platform.'),('RS-1XL','Modular robotic component pick-and-place assembly platform.'),('JM-100','Automated component pick-and-place/insertion platform.'),('JM-50','Automated component pick-and-place/insertion platform.'),('JM-20','Automated component pick-and-place/insertion platform for large boards.'),('JM-E01','Integrated two-robot component insertion and screw-fastening platform.')]:products.append(p('JUKI '+name,desc,b if name=='JM-E01' else a,life='commercial',typ='product',sector='robotics',sub='industrial_robotics'))
co=dict(company_id='cmp_3036376a-61dc-42f1-b8ff-2f30a84e9c26',products=products,evidence=[a,b],status='partial',coverage_note='Eight current robotic electronic-assembly platforms recorded from official current catalogue. Partial: legacy pick-and-place models, MR-series robot systems, automated sewing robot integration and directly supporting software/components require further qualification. General printers, inspection equipment and manual sewing machines not automatically assigned robotics or semiconductor fabrication scope.')
(out/'batch-0374.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
